sys_script_email.script:
// Role: one email script for the four notifications. It picks the right text from the event that triggered it.
(function runMailScript(current, template, email, email_action, event) {
  var notify = new CPMNotify();
  var events = new CPMConst().EVENT;
  var name = event.name + '';
  if (name == events.DIGEST) template.print(notify.ownerDigest(event.parm1 + '', event.parm2 + ''));
  else if (name == events.APPROVED) template.print(notify.approval(current));
  else if (name == events.REJECTED) template.print(notify.rejection(current));
  else if (name == events.SUBMITTED) template.print(notify.submitted(current));
  else if (name == events.ASSIGNED) template.print(notify.assigned(current));
  else if (name == events.TEAM) template.print(notify.teamDigest(current));
})(current, template, email, email_action, event);
